import{_ as o,o as t,c as i,a2 as n}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Hotkeys Settings","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Global","slug":"_1-global","link":"#_1-global","children":[{"level":3,"title":"Global Hotkeys Group","slug":"global-hotkeys-group","link":"#global-hotkeys-group","children":[]},{"level":3,"title":"Navigation & Function Keys Group","slug":"navigation-function-keys-group","link":"#navigation-function-keys-group","children":[]},{"level":3,"title":"Quick Navigation Mouse Triggers Group","slug":"quick-navigation-mouse-triggers-group","link":"#quick-navigation-mouse-triggers-group","children":[]},{"level":3,"title":"Recording a Hotkey","slug":"recording-a-hotkey","link":"#recording-a-hotkey","children":[]},{"level":3,"title":"Per-Favorite Hotkeys","slug":"per-favorite-hotkeys","link":"#per-favorite-hotkeys","children":[]}]},{"level":2,"title":"2. Plugin Actions","slug":"_2-plugin-actions","link":"#_2-plugin-actions","children":[]},{"level":2,"title":"3. Process Blacklist","slug":"_3-process-blacklist","link":"#_3-process-blacklist","children":[]}],"relativePath":"user-guide/settings/hotkeys-page.md","filePath":"user-guide/settings/hotkeys-page.md","lastUpdated":1791112464000}'),a={name:"user-guide/settings/hotkeys-page.md"};function r(l,e,s,c,d,g){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="hotkeys-settings" tabindex="-1">Hotkeys Settings <a class="header-anchor" href="#hotkeys-settings" aria-label="Permalink to &quot;Hotkeys Settings&quot;">​</a></h1><p>The Hotkeys settings page centralizes management of global summon hotkeys, in-app navigation keys, plugin action shortcuts, and foreground process filtering rules. The top tabs include: <strong>Global</strong>, <strong>Plugin Actions</strong>, and <strong>Process Blacklist</strong>.</p><h2 id="_1-global" tabindex="-1">1. Global <a class="header-anchor" href="#_1-global" aria-label="Permalink to &quot;1. Global&quot;">​</a></h2><h3 id="global-hotkeys-group" tabindex="-1">Global Hotkeys Group <a class="header-anchor" href="#global-hotkeys-group" aria-label="Permalink to &quot;Global Hotkeys Group&quot;">​</a></h3><ul><li><strong>Show/Hide Quick Search</strong>: Dedicated key recording box. Supports <strong>double-tap mode</strong> (default double <code>Ctrl</code>, configurable to double <code>Alt</code> or <code>Shift</code>) as well as <strong>standard key combinations</strong> (e.g. <code>Alt+Space</code>).</li><li><strong>Open full panel by default</strong>: Checkbox (default disabled). When enabled, the global summon hotkey opens the Full Window instead of the Quick Window. The first summon brings it to the foreground once; pressing the hotkey while it is visible but inactive refocuses it, and pressing it again when it is active returns to the Quick Window by default (or closes outright when <strong>Close Full Window on Repeat Hotkey</strong> is enabled). The window is not automatically kept topmost.</li><li><strong>Respond when focused on full-screen applications</strong>: Checkbox (default disabled). When enabled, Lertaro responds to hotkeys even when an exclusive fullscreen game or media player is active; when disabled, keys are bypassed silently to protect gameplay.</li><li><strong>Quick Jump</strong>: Default <code>Ctrl+G</code>. In file dialogs, jumps immediately to the directory most recently browsed in supported file managers.</li><li><strong>Quick Navigation Menu</strong>: No shortcut is assigned by default. You can assign an optional global shortcut to open the cascading menu. From the desktop or an ordinary app it uses desktop context; in File Explorer and native file dialogs it uses the current window context. File managers and file dialogs remain allowed even when ordinary foreground protections suppress global hotkeys.</li></ul><h3 id="navigation-function-keys-group" tabindex="-1">Navigation &amp; Function Keys Group <a class="header-anchor" href="#navigation-function-keys-group" aria-label="Permalink to &quot;Navigation &amp; Function Keys Group&quot;">​</a></h3><p>Provides dedicated key recording controls accepting custom single keys or combinations:</p><ul><li><strong>Select Next / Previous Item</strong>: Default <code>Ctrl+N</code> / <code>Ctrl+P</code> (equivalent to <code>↓</code> / <code>↑</code>).</li><li><strong>Jump to Result Modifier</strong>: Default <code>Ctrl</code>, used with numbers <code>1</code>–<code>9</code> for instant activation.</li><li><strong>Open Action Menu</strong>: Default <code>Ctrl+O</code> (equivalent to <code>→</code>). Both apply to the Quick Window and to the inline card outside file dialogs; the Full Window opens the same menu with right-click or the <code>Apps</code> key.</li><li><strong>Autocomplete from Selection</strong>: Default <code>Ctrl+Tab</code>.</li><li><strong>QuickLook Instant Preview</strong>: Default <code>Alt+P</code>.</li><li><strong>Previous / Next Search Term</strong>: Default <code>Alt+Up</code> / <code>Alt+Down</code>.</li><li><strong>Delete Search History Term</strong>: Default <code>Ctrl+Delete</code>.</li><li><strong>Open Full Window</strong>: Default <code>Ctrl+F</code>.</li><li><strong>Open LocalSend Window</strong>: Default <code>Ctrl+S</code>.</li><li><strong>Pin Window (Keep Visible)</strong>: Default <code>Ctrl+T</code>.</li><li><strong>Toggle Quick Panel</strong>: Default <code>Ctrl+F2</code>.</li></ul><h3 id="quick-navigation-mouse-triggers-group" tabindex="-1">Quick Navigation Mouse Triggers Group <a class="header-anchor" href="#quick-navigation-mouse-triggers-group" aria-label="Permalink to &quot;Quick Navigation Mouse Triggers Group&quot;">​</a></h3><ul><li><strong>Double-click left button on blank area</strong>: Checkbox (<strong>disabled by default</strong>). Pops up the Quick Navigation menu on desktop or File Explorer empty spaces.</li><li><strong>Middle-click on blank area</strong>: Checkbox (default enabled). Pops up the Quick Navigation menu on desktop, File Explorer, or open/save file dialogs.</li></ul><p>Only the desktop and File Explorer honor the double-click form; third-party file managers accept middle-click alone. Both triggers are skipped while the pointer is over Lertaro&#39;s own card, and both stay alive for file managers and dialogs even when a blacklist or fullscreen would normally silence global triggers.</p><h3 id="recording-a-hotkey" tabindex="-1">Recording a Hotkey <a class="header-anchor" href="#recording-a-hotkey" aria-label="Permalink to &quot;Recording a Hotkey&quot;">​</a></h3><p>Every key press goes into the box instead of the app behind it, which makes the recorder itself a set of gestures:</p><ul><li><strong><code>Escape</code></strong> cancels the recording and clears the value. There is no &quot;discard and restore&quot; — the box is empty the moment you press it.</li><li><strong><code>✕</code></strong> clears the box; <strong><code>↺</code></strong> restores that row&#39;s factory default. Exactly one of the two is shown at a time — clear while a combination is set, restore once it is empty.</li><li><strong>A bare modifier</strong> (<code>Ctrl</code>, <code>Alt</code>, <code>Shift</code>) is accepted only on rows that mean something by itself — the summon hotkey, which becomes a double-tap, and the jump modifier. On an ordinary combination row, pressing and releasing a lone modifier <strong>clears</strong> the row rather than saving a value that could never fire.</li><li><strong>Windows-reserved combinations</strong> (<code>Win+E</code>, <code>Win+D</code>, …) are refused: the value is coerced to empty, so the box simply goes blank.</li><li><strong>No conflict detection.</strong> Two rows can hold the same chord and nothing warns you; only favorite-item hotkeys report a duplicate or an OS-refused combination, and only after you apply.</li></ul><h3 id="per-favorite-hotkeys" tabindex="-1">Per-Favorite Hotkeys <a class="header-anchor" href="#per-favorite-hotkeys" aria-label="Permalink to &quot;Per-Favorite Hotkeys&quot;">​</a></h3><p>Every favorite (<a href="./favorites.html"><strong>Settings → Favorites</strong></a>) can carry its own <strong>OS-level global</strong> hotkey, which works even when Lertaro has no window open and jumps the foreground file manager to that folder. Unlike the recorder rows above it requires a modifier, refuses a lone modifier, and cannot use <code>F12</code>.</p><h2 id="_2-plugin-actions" tabindex="-1">2. Plugin Actions <a class="header-anchor" href="#_2-plugin-actions" aria-label="Permalink to &quot;2. Plugin Actions&quot;">​</a></h2><p>All action shortcuts registered by plugins (e.g. Copy Full Path <code>Ctrl+Shift+C</code>, Copy Name <code>Shift+C</code>, Cut <code>Ctrl+X</code>, Copy <code>Ctrl+C</code>, Paste <code>Ctrl+V</code>, Delete <code>Delete</code>, Permanent Delete <code>Shift+Delete</code>) are grouped here.</p><ul><li><strong>Categorized View</strong>: Neatly organized by the originating plugin.</li><li><strong>Rebindable</strong>: Each action includes its own key recording control.</li></ul><h2 id="_3-process-blacklist" tabindex="-1">3. Process Blacklist <a class="header-anchor" href="#_3-process-blacklist" aria-label="Permalink to &quot;3. Process Blacklist&quot;">​</a></h2><p>Configures silence rules for specific foreground applications. When a blacklisted process is focused, Lertaro bypasses all global hotkeys and mouse triggers without interception.</p><ul><li><strong>Case-Insensitive</strong>: Both <code>game.exe</code> and <code>game</code> are matched.</li><li><strong>Add Single Entry</strong>: Type the process name and click <strong>Add Process</strong>.</li><li><strong>Batch Editing</strong>: Click <strong>Generate Text</strong> to export current entries to multi-line text, or paste a list and click <strong>Apply to List</strong> for batch updates.</li><li><strong>File Dialog Exemption</strong>: Even if an application is blacklisted, its native file selection dialogs remain exempted, so Inline Search and Quick Navigation keep working.</li></ul>',22)])])}const p=o(a,[["render",r]]);export{h as __pageData,p as default};
